// Self-contained: every local import is inlined below. Requires only d3, motion, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useState } from 'react';
import * as d3 from 'd3';
import { motion } from 'motion/react';

// ---- inlined from data ----
/** Relative frequency of letters in English text. */
const letterFrequency = [
  { letter: 'E', frequency: 0.1202 },
  { letter: 'T', frequency: 0.091 },
  { letter: 'A', frequency: 0.0812 },
  { letter: 'O', frequency: 0.0768 },
  { letter: 'I', frequency: 0.0731 },
  { letter: 'N', frequency: 0.0695 },
  { letter: 'S', frequency: 0.0628 },
  { letter: 'R', frequency: 0.0602 },
  { letter: 'H', frequency: 0.0592 },
  { letter: 'D', frequency: 0.0432 },
  { letter: 'L', frequency: 0.0398 },
  { letter: 'U', frequency: 0.0288 },
  { letter: 'C', frequency: 0.0271 },
  { letter: 'M', frequency: 0.0261 },
  { letter: 'F', frequency: 0.023 },
  { letter: 'Y', frequency: 0.0211 },
  { letter: 'W', frequency: 0.0209 },
  { letter: 'G', frequency: 0.0203 },
  { letter: 'P', frequency: 0.0182 },
  { letter: 'B', frequency: 0.0149 }
];

/** Deterministic synthetic series so hot reloads do not reshuffle the chart. */
const timeSeries = Array.from({ length: 120 }, (_, i) => ({
  date: new Date(2024, 0, 1 + i * 3),
  value: 100 + Math.sin(i / 7) * 22 + Math.sin(i / 23) * 38 + i * 0.45
}));

const MARGIN = { top: 16, right: 16, bottom: 36, left: 44 };
const CYCLE_MS = 3200;
const TRANSITION = { duration: 0.75, ease: 'easeInOut' } as const;

/** One bar per category, sized by its frequency; the sort order cycles over it. */
export type Data = { letter: string; frequency: number }[];

const orders: { label: string; compare: (a: Data[number], b: Data[number]) => number }[] = [
  { label: 'Alphabetical', compare: (a, b) => a.letter.localeCompare(b.letter) },
  { label: 'Frequency, ascending', compare: (a, b) => a.frequency - b.frequency },
  { label: 'Frequency, descending', compare: (a, b) => b.frequency - a.frequency }
];

export default function BarChartTransitions({ data = letterFrequency, width }:
  { data?: Data; width: number }) {
  const height = Math.round(width * 0.5);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const [orderIndex, setOrderIndex] = useState(0);

  useEffect(() => {
    const id = window.setInterval(() => setOrderIndex((i) => (i + 1) % orders.length), CYCLE_MS);
    return () => window.clearInterval(id);
  }, []);

  const sortedLetters = useMemo(
    () => [...data].sort(orders[orderIndex].compare).map((d) => d.letter),
    [data, orderIndex]
  );

  const x = useMemo(
    () => d3.scaleBand().domain(sortedLetters).range([0, innerWidth]).padding(0.15),
    [sortedLetters, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(data, (d) => d.frequency) ?? 0])
        .nice()
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  const yTicks = useMemo(
    () => y.ticks(5).map((v) => ({ value: d3.format('.0%')(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`Bar chart of English letter frequency, sorted ${orders[orderIndex].label.toLowerCase()}`}
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g className="axis">
          {yTicks.map(({ value, offset }) => (
            <g key={value} transform={`translate(0,${offset})`}>
              <line className="grid" x1={0} x2={innerWidth} y1={0} y2={0} />
              <text x={-10} dy="0.32em" textAnchor="end">
                {value}
              </text>
            </g>
          ))}
        </g>

        <g className="axis" transform={`translate(0,${innerHeight})`}>
          <line x1={0} x2={innerWidth} y1={0} y2={0} />
          {data.map((d) => (
            <motion.g
              key={d.letter}
              animate={{ x: (x(d.letter) ?? 0) + x.bandwidth() / 2 }}
              transition={TRANSITION}
            >
              <line y1={0} y2={5} />
              <text y={18} textAnchor="middle">
                {d.letter}
              </text>
            </motion.g>
          ))}
        </g>

        {data.map((d) => (
          <motion.rect
            key={d.letter}
            y={y(d.frequency)}
            height={innerHeight - y(d.frequency)}
            width={x.bandwidth()}
            fill="var(--accent)"
            style={{ mixBlendMode: 'multiply' }}
            animate={{ x: x(d.letter) ?? 0 }}
            transition={TRANSITION}
          />
        ))}
      </g>
    </svg>
  );
}
